package com.pirris.mapper;

import java.util.List;

import org.mapstruct.Mapper;
import org.mapstruct.Mapping;
import org.mapstruct.MappingConstants;

import com.pirris.dto.service.ServiceRateDto;
import com.pirris.dto.service.TrainingServiceDto;
import com.pirris.model.ServiceRateModel;
import com.pirris.model.TrainingServiceModel;

/**
 * Compile-time mapper from {@link TrainingServiceModel} / {@link ServiceRateModel}
 * to the Servizi view DTOs. Generated by MapStruct as a CDI bean.
 */
@Mapper(componentModel = MappingConstants.ComponentModel.CDI)
public interface ServiceCatalogMapper {

    // ---- entity -> DTO (reads) ----

    ServiceRateDto toRateDto(ServiceRateModel rate);

    List<ServiceRateDto> toRateDtos(List<ServiceRateModel> rates);

    /** A service with its (already mapped) rates. */
    @Mapping(target = "id", source = "service.id")
    @Mapping(target = "name", source = "service.name")
    @Mapping(target = "description", source = "service.description")
    @Mapping(target = "durationMinutes", source = "service.durationMinutes")
    @Mapping(target = "colorHex", source = "service.colorHex")
    @Mapping(target = "archived", source = "service.archived")
    @Mapping(target = "rates", source = "rates")
    TrainingServiceDto toDto(TrainingServiceModel service, List<ServiceRateDto> rates);
}
